// ── Labels ──
const panelLabels = ['(a)', '(b)', '(c)', '(d)'];
const panelNames = ['Right circular cylinder', 'Solid sphere', 'Solid cone', 'Hollowed right\ncircular cylinder'];
thumbPositions.forEach((tp, i) => {
  addLabel(panelLabels[i], new THREE.Vector3(tp.x, -2.6, 0), { color: '#555', fontSize: '12px' });
  addLabel(panelNames[i].replace('\n', ' '), new THREE.Vector3(tp.x, -2.9, 0), { color: '#555', fontSize: '10px' });
});
addLabel('Axis of revolution', new THREE.Vector3(-2.2, 0.15, 0), { color: '#555', fontSize: '11px' });

// ── State ──
let activeType = 'Cylinder';
let sweepAngle = Math.PI * 2;
let animating = false;

function switchSolid(type) {
  activeType = type;
  rebuildSolid(type, sweepAngle);
  for (const key in regions) regions[key].visible = (key === type);
  thumbMeshes.forEach((m, i) => {
    m.material.opacity = thumbPositions[i].type === type ? 0.9 : 0.3;
  });
}
switchSolid('Cylinder');

// ── UI wiring ──
document.getElementById('solidType').addEventListener('change', (e) => {
  switchSolid(e.target.value);
  sweepAngle = Math.PI * 2;
  rebuildSolid(activeType, sweepAngle);
});

document.getElementById('revolve').addEventListener('change', (e) => {
  animating = e.target.checked;
  if (animating) sweepAngle = 0;
});

// ── Demo steps ──
const demoSteps = [
  { title: '(a) Rectangle → cylinder', state: { solidType: 'Cylinder', revolve: true } },
  { title: '(b) Semicircle → sphere', state: { solidType: 'Sphere', revolve: true } },
  { title: '(c) Right triangle → cone', state: { solidType: 'Cone', revolve: true } },
  { title: '(d) Offset rectangle → hollow cylinder', state: { solidType: 'Hollow cylinder', revolve: true } }
];
let demoIdx = -1;
let demoRunning = false;

function goToStep(idx) {
  if (idx < 0 || idx >= demoSteps.length) return;
  demoIdx = idx;
  const st = demoSteps[idx].state;
  document.getElementById('solidType').value = st.solidType;
  document.getElementById('revolve').checked = st.revolve;
  switchSolid(st.solidType);
  animating = st.revolve;
  if (animating) sweepAngle = 0;
  showPopup(demoSteps[idx].title, demoSteps[idx].narration || '');
}

document.getElementById('btnDemo').addEventListener('click', () => {
  if (demoRunning) return;
  demoRunning = true;
  demoIdx = -1;
  const advance = () => {
    demoIdx++;
    if (demoIdx >= demoSteps.length) { demoRunning = false; return; }
    goToStep(demoIdx);
    setTimeout(advance, 4000);
  };
  advance();
});

// ── Animation loop ──
const _clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = _clock.getDelta();
  if (animating && sweepAngle < Math.PI * 2) {
    sweepAngle = Math.min(sweepAngle + dt * 2.5, Math.PI * 2);
    rebuildSolid(activeType, sweepAngle);
    if (sweepAngle >= Math.PI * 2) {
      animating = false;
      document.getElementById('revolve').checked = false;
    }
  }
  // Billboard 2D regions toward camera
  regionGroup.quaternion.copy(camera.quaternion);
}
tick();

// ── Camera ─
setCameraView({
  projection: 'perspective',
  azimuthDeg: 75,
  elevationDeg: 12,
  rollDeg: 0,
  heightFraction: 0.62
});
// @FIGURE_CODE_END

