userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Solid
  <select id="solidType">
    <option value="Cylinder" selected>Cylinder</option>
    <option value="Sphere">Sphere</option>
    <option value="Cone">Cone</option>
    <option value="Hollow cylinder">Hollow cylinder</option>
  </select>
</label>
<label><input type="checkbox" id="revolve"> Animate revolution</label>
<button id="btnDemo">▶ Demo steps</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element specs ─────────────────────────────────────────────────────────
  title label      → addLabel 'Some Familiar Solids of Revolution' at top center
  axis line        → Line per panel, horizontal through solid center, #222
  rotation arrow   → partial TorusGeometry + ConeGeometry tip at right end of axis
  2D rectangle     → ShapeGeometry flat, fill #cfe9e6, stroke #14a3a3
  2D semicircle    → ShapeGeometry flat
  2D triangle      → ShapeGeometry flat
  2D offset rect   → ShapeGeometry flat (floating above axis)
  cylinder         → LatheGeometry profile [(0,-1.3),(1,-1.3),(1,1.3),(0,1.3)] rotated to X
  sphere           → LatheGeometry semicircle profile r=1.2
  cone             → LatheGeometry profile [(0,-1.3),(1,1.3),(0,1.3)]
  hollow cyl       → LatheGeometry tube profile [(0.5,-1.3),(1,-1.3),(1,1.3),(0.5,1.3),(0.5,-1.3)] closed
  4 panels         → each at X=-4.5,-1.5,+1.5,+4.5 with region above, solid below
  panel labels     → addLabel (a)-(d) fontSize 16px bold
  name labels      → addLabel solid names fontSize 13px
─────────────────────────────────────────────────────────────────────────── */

const TEAL_FILL = 0xcfe9e6;
const TEAL_STROKE = 0x14a3a3;
const TEAL_SOLID = 0x3fb0b0;
const TEAL_LIGHT = 0xe2f4f1;
const AXIS_COLOR = 0x222222;

// ── Lights ─
const ambLight = new THREE.AmbientLight(0xffffff, 0.65);
scene.add(ambLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.85);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.35);
dirLight2.position.set(-2, 3, -3);
scene.add(dirLight2);

// ── Materials ──
const solidMat = new THREE.MeshPhongMaterial({
  color: TEAL_SOLID, specular: 0x88dddd, shininess: 60,
  side: THREE.DoubleSide, transparent: true, opacity: 1.0
});
const solidMatDim = new THREE.MeshPhongMaterial({
  color: TEAL_SOLID, specular: 0x88dddd, shininess: 60,
  side: THREE.DoubleSide, transparent: true, opacity: 0.35
});
const fillMat = new THREE.MeshBasicMaterial({ color: TEAL_FILL, side: THREE.DoubleSide, transparent: true, opacity: 0.85 });
const fillMatDim = new THREE.MeshBasicMaterial({ color: TEAL_FILL, side: THREE.DoubleSide, transparent: true, opacity: 0.3 });
const strokeMat = new THREE.LineBasicMaterial({ color: TEAL_STROKE });
const strokeMatDim = new THREE.LineBasicMaterial({ color: TEAL_STROKE, transparent: true, opacity: 0.3 });
const axisMat = new THREE.LineBasicMaterial({ color: AXIS_COLOR });
const axisMatDim = new THREE.LineBasicMaterial({ color: AXIS_COLOR, transparent: true, opacity: 0.3 });

// ── Profile generators ──
function cylinderProfile() {
  return [new THREE.Vector2(0, -1.3), new THREE.Vector2(1.0, -1.3), new THREE.Vector2(1.0, 1.3), new THREE.Vector2(0, 1.3)];
}
function sphereProfile() {
  const pts = [];
  for (let i = 0; i <= 32; i++) {
    const a = -Math.PI / 2 + Math.PI * (i / 32);
    pts.push(new THREE.Vector2(Math.cos(a) * 1.2, Math.sin(a) * 1.2));
  }
  return pts;
}
function coneProfile() {
  return [new THREE.Vector2(0, -1.3), new THREE.Vector2(1.0, 1.3), new THREE.Vector2(0, 1.3)];
}
function hollowProfile() {
  return [
    new THREE.Vector2(0.5, -1.3),
    new THREE.Vector2(1.0, -1.3),
    new THREE.Vector2(1.0, 1.3),
    new THREE.Vector2(0.5, 1.3),
    new THREE.Vector2(0.5, -1.3)
  ];
}

const profiles = {
  'Cylinder': cylinderProfile,
  'Sphere': sphereProfile,
  'Cone': coneProfile,
  'Hollow cylinder': hollowProfile
};

// ── Build lathe geometry about X axis ──
function buildLathe(profile, segments = 64, thetaLength = Math.PI * 2) {
  const geom = new THREE.LatheGeometry(profile, segments, 0, thetaLength);
  geom.rotateZ(-Math.PI / 2); // align axis with X
  return geom;
}

// ── 2D Region builders ──
function makeRectRegion(w, h, offsetY) {
  const shape = new THREE.Shape();
  shape.moveTo(-w / 2, offsetY);
  shape.lineTo(w / 2, offsetY);
  shape.lineTo(w / 2, offsetY + h);
  shape.lineTo(-w / 2, offsetY + h);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

function makeSemicircleRegion(r) {
  const shape = new THREE.Shape();
  shape.moveTo(-r, 0);
  shape.absarc(0, 0, r, 0, Math.PI, false);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape, 32);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom, 1);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

function makeTriangleRegion(base, height) {
  const shape = new THREE.Shape();
  shape.moveTo(-base / 2, 0);
  shape.lineTo(base / 2, 0);
  shape.lineTo(base / 2, height);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

// ── Panel data ──
const panelData = [
  { x: -4.5, type: 'Cylinder', label: '(a)', name: 'Right circular cylinder' },
  { x: -1.5, type: 'Sphere', label: '(b)', name: 'Solid sphere' },
  { x: 1.5, type: 'Cone', label: '(c)', name: 'Solid cone' },
  { x: 4.5, type: 'Hollow cylinder', label: '(d)', name: 'Hollowed right circular cylinder' }
];

const regions = {
  'Cylinder': makeRectRegion(2.6, 1.0, 0),
  'Sphere': makeSemicircleRegion(1.2),
  'Cone': makeTriangleRegion(2.6, 1.0),
  'Hollow cylinder': makeRectRegion(2.6, 0.5, 0.5)
};

// ── Build all four panels ──
const panelGroups = [];
const panelSolids = [];
const panelRegions = [];
const panelAxes = [];
const panelArrows = [];
const panelScale = 0.42;

panelData.forEach((pd, i) => {
  const group = new THREE.Group();
  group.position.set(pd.x, 0, 0);
  scene.add(group);
  panelGroups.push(group);

  // 3D solid
  const geom = buildLathe(profiles[pd.type](), 48);
  const mesh = new THREE.Mesh(geom, solidMat.clone());
  mesh.scale.setScalar(panelScale);
  mesh.position.set(0, -0.8, 0);
  group.add(mesh);
  panelSolids.push(mesh);

  // Axis line through solid
  const axGeom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.8 * panelScale * 2, -0.8, 0),
    new THREE.Vector3(1.8 * panelScale * 2, -0.8, 0)
  ]);
  const axLine = new THREE.Line(axGeom, axisMat.clone());
  group.add(axLine);
  panelAxes.push(axLine);

  // Rotation arrow at right end of axis
  const arrowG = new THREE.Group();
  const torusGeom = new THREE.TorusGeometry(0.22, 0.015, 8, 24, Math.PI * 1.5);
  const torusMat = new THREE.MeshBasicMaterial({ color: AXIS_COLOR });
  const torusMesh = new THREE.Mesh(torusGeom, torusMat);
  torusMesh.rotation.x = Math.PI / 2;
  arrowG.add(torusMesh);
  const tipGeom = new THREE.ConeGeometry(0.04, 0.1, 8);
  const tipMesh = new THREE.Mesh(tipGeom, torusMat.clone());
  tipMesh.position.set(0.22, 0, 0);
  tipMesh.rotation.z = -Math.PI / 2;
  arrowG.add(tipMesh);
  arrowG.position.set(1.6 * panelScale * 2, -0.8, 0);
  group.add(arrowG);
  panelArrows.push(arrowG);

  // 2D region above
  const region = regions[pd.type].clone();
  region.scale.setScalar(panelScale);
  region.position.set(0, 1.6, 0);
  group.add(region);
  panelRegions.push(region);

  // Region axis line
  const rAxGeom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.8 * panelScale * 2, 1.6, 0),
    new THREE.Vector3(1.8 * panelScale * 2, 1.6, 0)
  ]);
  const rAxLine = new THREE.Line(rAxGeom, axisMat.clone());
  group.add(rAxLine);

  // Register interactive
  registerInteractive(mesh, {
    title: pd.name,
    body: `Panel ${pd.label}: A 2D region revolved about the axis produces this ${pd.name.toLowerCase()}. Click to focus.`,
    tooltip: pd.name,
    onClick: () => {
      document.getElementById('solidType').value = pd.type;
      focusPanel(pd.type);
    }
  });
});

// ── Title label ──
addLabel('<b>Some Familiar Solids of Revolution</b>', new THREE.Vector3(0, 3.8, 0), {
  color: '#111', fontSize: '20px', bold: true
});

// ── Panel labels ──
panelData.forEach((pd, i) => {
  addLabel(`<b>${pd.label}</b>`, new THREE.Vector3(pd.x, -2.4, 0), {
    color: '#333', fontSize: '16px', bold: true
  });
  addLabel(pd.name, new THREE.Vector3(pd.x, -2.9, 0), {
    color: '#555', fontSize: '13px'
  });
});

// ── "Axis of revolution" label on first panel ──
addLabel('Axis of revolution', new THREE.Vector3(-4.5, 0.9, 0), {
  color: '#555', fontSize: '11px'
});

// ── Focus state ──
let activeType = 'Cylinder';
let sweepAngle = Math.PI * 2;
let animating = false;
let focusedSolidMesh = null;

// Focused solid (larger, centered above panels)
const focusGroup = new THREE.Group();
focusGroup.position.set(0, 0, 2.5);
scene.add(focusGroup);

const focusAxisGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-3, 0, 0), new THREE.Vector3(3, 0, 0)
]);
const focusAxisLine = new THREE.Line(focusAxisGeom, axisMat.clone());
focusGroup.add(focusAxisLine);

// Focus rotation arrow
const focusArrowG = new THREE.Group();
const fTorusGeom = new THREE.TorusGeometry(0.35, 0.02, 8, 32, Math.PI * 1.5);
const fTorusMat = new THREE.MeshBasicMaterial({ color: AXIS_COLOR });
const fTorusMesh = new THREE.Mesh(fTorusGeom, fTorusMat);
fTorusMesh.rotation.x = Math.PI / 2;
focusArrowG.add(fTorusMesh);
const fTipGeom = new THREE.ConeGeometry(0.06, 0.15, 8);
const fTipMesh = new THREE.Mesh(fTipGeom, fTorusMat.clone());
fTipMesh.position.set(0.35, 0, 0);
fTipMesh.rotation.z = -Math.PI / 2;
focusArrowG.add(fTipMesh);
focusArrowG.position.set(2.4, 0, 0);
focusGroup.add(focusArrowG);

// Focus 2D region
const focusRegionGroup = new THREE.Group();
focusRegionGroup.position.set(0, 2.2, 0);
focusGroup.add(focusRegionGroup);

const focusRegions = {};
for (const key in regions) {
  const r = regions[key].clone();
  r.visible = false;
  focusRegionGroup.add(r);
  focusRegions[key] = r;
}

// Focus region axis
const fRAxGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-2, 0, 0), new THREE.Vector3(2, 0, 0)
]);
const fRAxLine = new THREE.Line(fRAxGeom, axisMat.clone());
focusRegionGroup.add(fRAxLine);

function rebuildFocusSolid(type, sweep = Math.PI * 2) {
  if (focusedSolidMesh) {
    focusGroup.remove(focusedSolidMesh);
    focusedSolidMesh.geometry.dispose();
    focusedSolidMesh.material.dispose();
  }
  const geom = buildLathe(profiles[type](), 64, sweep);
  focusedSolidMesh = new THREE.Mesh(geom, solidMat.clone());
  focusGroup.add(focusedSolidMesh);
}

function focusPanel(type) {
  activeType = type;
  rebuildFocusSolid(type, sweepAngle);
  for (const key in focusRegions) {
    focusRegions[key].visible = (key === type);
  }
  // Highlight active panel, dim others
  panelData.forEach((pd, i) => {
    const isActive = pd.type === type;
    panelSolids[i].material.opacity = isActive ? 0.95 : 0.35;
    panelSolids[i].material.transparent = true;
  });
}

focusPanel('Cylinder');
focusGroup.visible = true;

// ── UI wiring ──
document.getElementById('solidType').addEventListener('change', (e) => {
  focusPanel(e.target.value);
  sweepAngle = Math.PI * 2;
  rebuildFocusSolid(activeType, sweepAngle);
});

document.getElementById('revolve').addEventListener('change', (e) => {
  animating = e.target.checked;
  if (animating) sweepAngle = 0;
});

// ── Demo steps ──
const demoSteps = [
  { title: '(a) Rectangle → cylinder', narration: 'A rectangle sitting on the axis, revolved 360° about that axis, sweeps out a right circular cylinder; the rectangle\'s height becomes the radius and its width the length.', state: { solidType: 'Cylinder', revolve: true } },
  { title: '(b) Semicircle → sphere', narration: 'A semicircle with its diameter on the axis revolves into a solid sphere; the semicircle\'s radius is the sphere\'s radius.', state: { solidType: 'Sphere', revolve: true } },
  { title: '(c) Right triangle → cone', narration: 'A right triangle with one leg on the axis revolves into a solid cone; the on-axis leg is the height and the perpendicular leg the base radius.', state: { solidType: 'Cone', revolve: true } },
  { title: '(d) Offset rectangle → hollow cylinder', narration: 'A rectangle held above (not touching) the axis leaves a gap when revolved, producing a hollowed right circular cylinder (a tube) with an empty bore along the axis.', state: { solidType: 'Hollow cylinder', revolve: true } }
];
let demoIdx = -1;
let demoRunning = false;

function goToStep(idx) {
  if (idx < 0 || idx >= demoSteps.length) return;
  demoIdx = idx;
  const st = demoSteps[idx].state;
  document.getElementById('solidType').value = st.solidType;
  document.getElementById('revolve').checked = st.revolve;
  focusPanel(st.solidType);
  animating = st.revolve;
  if (animating) sweepAngle = 0;
  showPopup(demoSteps[idx].title, demoSteps[idx].narration);
}

document.getElementById('btnDemo').addEventListener('click', () => {
  if (demoRunning) return;
  demoRunning = true;
  demoIdx = -1;
  const advance = () => {
    demoIdx++;
    if (demoIdx >= demoSteps.length) { demoRunning = false; return; }
    goToStep(demoIdx);
    setTimeout(advance, 4500);
  };
  advance();
});

// ── Animation loop ──
const _clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = _clock.getDelta();
  if (animating && sweepAngle < Math.PI * 2) {
    sweepAngle = Math.min(sweepAngle + dt * 2.0, Math.PI * 2);
    rebuildFocusSolid(activeType, sweepAngle);
    if (sweepAngle >= Math.PI * 2) {
      animating = false;
      document.getElementById('revolve').checked = false;
    }
  }
  // Billboard 2D regions toward camera
  focusRegionGroup.quaternion.copy(camera.quaternion);
  panelRegions.forEach(r => {
    r.quaternion.copy(camera.quaternion);
  });
}
tick();

// ── Camera ──
setCameraView({
  projection: 'perspective',
  azimuthDeg: 75,
  elevationDeg: 12,
  rollDeg: 0,
  heightFraction: 0.62
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
