Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Solid
  <select id="solidType">
    <option value="Cylinder" selected>Cylinder</option>
    <option value="Sphere">Sphere</option>
    <option value="Cone">Cone</option>
    <option value="Hollow cylinder">Hollow cylinder</option>
  </select>
</label>
<label><input type="checkbox" id="revolve"> Animate revolution</label>
<button id="btnDemo">▶ Demo steps</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element specs ─────────────────────────────────────────────────────────
  title label      → addLabel 'Some Familiar Solids of Revolution' top center, 20px bold
  4 panels         → x = -5.25, -1.75, 1.75, 5.25
  2D regions       → ShapeGeometry in XY plane at y≈2.2, teal fill + stroke
  axis lines       → horizontal Line at y≈1.0 per panel, #222
  rotation arrows  → TorusGeometry arc + ConeGeometry tip at right end of axis
  3D solids        → LatheGeometry (axis along X) at y≈-1.2, scale 0.85
  name labels      → addLabel below solids, 18px
  panel letters    → addLabel (a)-(d) at bottom, 20px bold
  axis label       → addLabel 'Axis of revolution' below panel (a) axis
  camera           → orthographic, azimuth 8°, elevation 3°, heightFraction 0.72
─────────────────────────────────────────────────────────────────────────── */

const TEAL_FILL = 0xcfe9e6;
const TEAL_STROKE = 0x14a3a3;
const TEAL_SOLID = 0x4db8b8;
const AXIS_COLOR = 0x222222;

// ── Lights ──
const ambLight = new THREE.AmbientLight(0xffffff, 0.7);
scene.add(ambLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(2, 4, 6);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
dirLight2.position.set(-3, 2, -4);
scene.add(dirLight2);

// ── Materials ──
const solidMat = new THREE.MeshPhongMaterial({
  color: TEAL_SOLID, specular: 0x99eeee, shininess: 50,
  side: THREE.DoubleSide, transparent: true, opacity: 0.92
});
const fillMat = new THREE.MeshBasicMaterial({ color: TEAL_FILL, side: THREE.DoubleSide, transparent: true, opacity: 0.8 });
const strokeMat = new THREE.LineBasicMaterial({ color: TEAL_STROKE });
const axisMat = new THREE.LineBasicMaterial({ color: AXIS_COLOR });

// ── Profile generators (for LatheGeometry, Y-axis = revolution axis) ──
function cylinderProfile() {
  return [new THREE.Vector2(0, -1.3), new THREE.Vector2(1.0, -1.3), new THREE.Vector2(1.0, 1.3), new THREE.Vector2(0, 1.3)];
}
function sphereProfile() {
  const pts = [];
  for (let i = 0; i <= 32; i++) {
    const a = -Math.PI / 2 + Math.PI * (i / 32);
    pts.push(new THREE.Vector2(Math.cos(a) * 1.1, Math.sin(a) * 1.1));
  }
  return pts;
}
function coneProfile() {
  return [new THREE.Vector2(0, -1.3), new THREE.Vector2(1.0, 1.3), new THREE.Vector2(0, 1.3)];
}
function hollowProfile() {
  return [
    new THREE.Vector2(0.5, -1.3), new THREE.Vector2(1.0, -1.3),
    new THREE.Vector2(1.0, 1.3), new THREE.Vector2(0.5, 1.3),
    new THREE.Vector2(0.5, -1.3)
  ];
}

const profiles = {
  'Cylinder': cylinderProfile,
  'Sphere': sphereProfile,
  'Cone': coneProfile,
  'Hollow cylinder': hollowProfile
};

// ── Build lathe geometry about X axis ──
function buildLathe(profile, segments = 48, thetaLength = Math.PI * 2) {
  const geom = new THREE.LatheGeometry(profile, segments, 0, thetaLength);
  geom.rotateZ(-Math.PI / 2); // align revolution axis with world X
  return geom;
}

// ── 2D Region builders (in XY plane) ──
function makeRectRegion(w, h, offsetY) {
  const shape = new THREE.Shape();
  shape.moveTo(-w / 2, offsetY);
  shape.lineTo(w / 2, offsetY);
  shape.lineTo(w / 2, offsetY + h);
  shape.lineTo(-w / 2, offsetY + h);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

function makeSemicircleRegion(r) {
  const shape = new THREE.Shape();
  shape.moveTo(-r, 0);
  shape.absarc(0, 0, r, 0, Math.PI, false);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape, 32);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom, 1);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

function makeTriangleRegion(base, height) {
  const shape = new THREE.Shape();
  shape.moveTo(-base / 2, 0);
  shape.lineTo(base / 2, 0);
  shape.lineTo(base / 2, height);
  shape.closePath();
  const geom = new THREE.ShapeGeometry(shape);
  const mesh = new THREE.Mesh(geom, fillMat.clone());
  const edges = new THREE.EdgesGeometry(geom);
  const line = new THREE.LineSegments(edges, strokeMat.clone());
  const g = new THREE.Group();
  g.add(mesh); g.add(line);
  return g;
}

// ── Panel data ──
const panelData = [
  { x: -5.25, type: 'Cylinder', label: '(a)', name: 'Right circular cylinder' },
  { x: -1.75, type: 'Sphere', label: '(b)', name: 'Solid sphere' },
  { x: 1.75, type: 'Cone', label: '(c)', name: 'Solid cone' },
  { x: 5.25, type: 'Hollow cylinder', label: '(d)', name: 'Hollowed right circular cylinder' }
];

const regions = {
  'Cylinder': makeRectRegion(2.2, 1.0, 0),
  'Sphere': makeSemicircleRegion(1.1),
  'Cone': makeTriangleRegion(2.2, 1.0),
  'Hollow cylinder': makeRectRegion(2.2, 0.4, 0.3)
};

const SOLID_SCALE = 0.85;
const REGION_Y = 2.2;
const AXIS_Y = 1.0;
const SOLID_Y = -1.2;

// ── Build all four panels ──
const panelGroups = [];
const panelSolids = [];
const panelSolidMeshes = [];

panelData.forEach((pd, i) => {
  const group = new THREE.Group();
  group.position.set(pd.x, 0, 0);
  scene.add(group);
  panelGroups.push(group);

  // 3D solid
  const geom = buildLathe(profiles[pd.type](), 48);
  const mesh = new THREE.Mesh(geom, solidMat.clone());
  mesh.scale.setScalar(SOLID_SCALE);
  mesh.position.set(0, SOLID_Y, 0);
  group.add(mesh);
  panelSolids.push(mesh);
  panelSolidMeshes.push(mesh);

  // Axis line through solid
  const axGeom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.8, SOLID_Y, 0),
    new THREE.Vector3(1.8, SOLID_Y, 0)
  ]);
  const axLine = new THREE.Line(axGeom, axisMat.clone());
  group.add(axLine);

  // Rotation arrow at right end of solid axis
  const arrowG = new THREE.Group();
  const torusGeom = new THREE.TorusGeometry(0.18, 0.012, 8, 24, Math.PI * 1.5);
  const torusMat = new THREE.MeshBasicMaterial({ color: AXIS_COLOR });
  const torusMesh = new THREE.Mesh(torusGeom, torusMat);
  torusMesh.rotation.x = Math.PI / 2;
  arrowG.add(torusMesh);
  const tipGeom = new THREE.ConeGeometry(0.035, 0.09, 8);
  const tipMesh = new THREE.Mesh(tipGeom, torusMat.clone());
  tipMesh.position.set(0.18, 0, 0);
  tipMesh.rotation.z = -Math.PI / 2;
  arrowG.add(tipMesh);
  arrowG.position.set(1.55, SOLID_Y, 0);
  group.add(arrowG);

  // 2D region above
  const region = regions[pd.type].clone();
  region.position.set(0, REGION_Y, 0);
  group.add(region);

  // Region axis line
  const rAxGeom = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-1.6, REGION_Y, 0),
    new THREE.Vector3(1.6, REGION_Y, 0)
  ]);
  const rAxLine = new THREE.Line(rAxGeom, axisMat.clone());
  group.add(rAxLine);

  // Region rotation arrow
  const rArrowG = new THREE.Group();
  const rTorusGeom = new THREE.TorusGeometry(0.15, 0.01, 8, 20, Math.PI * 1.5);
  const rTorusMesh = new THREE.Mesh(rTorusGeom, torusMat.clone());
  rTorusMesh.rotation.x = Math.PI / 2;
  rArrowG.add(rTorusMesh);
  const rTipGeom = new THREE.ConeGeometry(0.03, 0.08, 8);
  const rTipMesh = new THREE.Mesh(rTipGeom, torusMat.clone());
  rTipMesh.position.set(0.15, 0, 0);
  rTipMesh.rotation.z = -Math.PI / 2;
  rArrowG.add(rTipMesh);
  rArrowG.position.set(1.4, REGION_Y, 0);
  group.add(rArrowG);

  // Register interactive
  registerInteractive(mesh, {
    title: pd.name,
    body: `Panel ${pd.label}: A 2D region revolved about the axis produces this ${pd.name.toLowerCase()}.`,
    tooltip: pd.name,
    onClick: () => {
      document.getElementById('solidType').value = pd.type;
      highlightPanel(pd.type);
    }
  });
});

// ── Title label ──
addLabel('<b>Some Familiar Solids of Revolution</b>', new THREE.Vector3(0, 4.2, 0), {
  color: '#111', fontSize: '20px', bold: true
});

// ── Panel labels ──
panelData.forEach((pd) => {
  addLabel(`<b>${pd.label}</b>`, new THREE.Vector3(pd.x, -3.6, 0), {
    color: '#222', fontSize: '20px', bold: true
  });
  addLabel(pd.name, new THREE.Vector3(pd.x, -3.0, 0), {
    color: '#444', fontSize: '18px'
  });
});

// ── "Axis of revolution" label on first panel ──
addLabel('Axis of revolution', new THREE.Vector3(-5.25, 0.4, 0), {
  color: '#444', fontSize: '14px'
});

// ── Highlight / animation state ──
let activeType = 'Cylinder';
let sweepAngle = Math.PI * 2;
let animating = false;

function highlightPanel(type) {
  activeType = type;
  panelData.forEach((pd, i) => {
    const isActive = pd.type === type;
    panelSolids[i].material.opacity = isActive ? 0.95 : 0.55;
  });
}

function rebuildSolid(type, sweep = Math.PI * 2) {
  const idx = panelData.findIndex(p => p.type === type);
  if (idx < 0) return;
  const oldMesh = panelSolids[idx];
  const group = panelGroups[idx];
  const pos = oldMesh.position.clone();
  const scale = oldMesh.scale.clone();
  group.remove(oldMesh);
  oldMesh.geometry.dispose();
  oldMesh.material.dispose();
  const geom = buildLathe(profiles[type](), 48, sweep);
  const mesh = new THREE.Mesh(geom, solidMat.clone());
  mesh.scale.copy(scale);
  mesh.position.copy(pos);
  mesh.material.opacity = 0.95;
  group.add(mesh);
  panelSolids[idx] = mesh;
  registerInteractive(mesh, {
    title: panelData[idx].name,
    body: `Panel ${panelData[idx].label}: A 2D region revolved about the axis produces this ${panelData[idx].name.toLowerCase()}.`,
    tooltip: panelData[idx].name,
    onClick: () => {
      document.getElementById('solidType').value = type;
      highlightPanel(type);
    }
  });
}

highlightPanel('Cylinder');

// ── UI wiring ──
document.getElementById('solidType').addEventListener('change', (e) => {
  highlightPanel(e.target.value);
  sweepAngle = Math.PI * 2;
  rebuildSolid(activeType, sweepAngle);
});

document.getElementById('revolve').addEventListener('change', (e) => {
  animating = e.target.checked;
  if (animating) sweepAngle = 0;
});

// ── Demo steps ──
const demoSteps = [
  { title: '(a) Rectangle → cylinder', narration: 'A rectangle sitting on the axis, revolved 360° about that axis, sweeps out a right circular cylinder; the rectangle\'s height becomes the radius and its width the length.', state: { solidType: 'Cylinder', revolve: true } },
  { title: '(b) Semicircle → sphere', narration: 'A semicircle with its diameter on the axis revolves into a solid sphere; the semicircle\'s radius is the sphere\'s radius.', state: { solidType: 'Sphere', revolve: true } },
  { title: '(c) Right triangle → cone', narration: 'A right triangle with one leg on the axis revolves into a solid cone; the on-axis leg is the height and the perpendicular leg the base radius.', state: { solidType: 'Cone', revolve: true } },
  { title: '(d) Offset rectangle → hollow cylinder', narration: 'A rectangle held above (not touching) the axis leaves a gap when revolved, producing a hollowed right circular cylinder (a tube) with an empty bore along the axis.', state: { solidType: 'Hollow cylinder', revolve: true } }
];
let demoIdx = -1;
let demoRunning = false;

function goToStep(idx) {
  if (idx < 0 || idx >= demoSteps.length) return;
  demoIdx = idx;
  const st = demoSteps[idx].state;
  document.getElementById('solidType').value = st.solidType;
  document.getElementById('revolve').checked = st.revolve;
  highlightPanel(st.solidType);
  animating = st.revolve;
  if (animating) sweepAngle = 0;
  showPopup(demoSteps[idx].title, demoSteps[idx].narration);
}

document.getElementById('btnDemo').addEventListener('click', () => {
  if (demoRunning) return;
  demoRunning = true;
  demoIdx = -1;
  const advance = () => {
    demoIdx++;
    if (demoIdx >= demoSteps.length) { demoRunning = false; return; }
    goToStep(demoIdx);
    setTimeout(advance, 4500);
  };
  advance();
});

// ── Animation loop ──
const _clock = new THREE.Clock();
function tick() {
  requestAnimationFrame(tick);
  const dt = _clock.getDelta();
  if (animating && sweepAngle < Math.PI * 2) {
    sweepAngle = Math.min(sweepAngle + dt * 2.0, Math.PI * 2);
    rebuildSolid(activeType, sweepAngle);
    if (sweepAngle >= Math.PI * 2) {
      animating = false;
      document.getElementById('revolve').checked = false;
    }
  }
}
tick();

// ── Camera: front-on orthographic matching flat textbook layout ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 8,
  elevationDeg: 3,
  rollDeg: 0,
  heightFraction: 0.72
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

